-- =====================================================================
-- 37 — THỬ 10 MÓN ĐẦU (để khoanh vùng lỗi không đăng nhập được)
-- =====================================================================
-- Chạy SAU patch 36 (đã gỡ sạch). Chỉ thêm 10 cải trang: item 2032–2041, part 2099–2128.
-- Nếu đăng nhập ĐƯỢC -> lỗi do SỐ LƯỢNG vật phẩm, không phải do dữ liệu.
-- Nếu vẫn KHÔNG đăng nhập được -> lỗi nằm trong chính dữ liệu 10 món này.
-- Chạy lại nhiều lần vẫn an toàn (tự xoá trước khi ghi). Khởi động lại server sau khi chạy.
-- =====================================================================

DELETE FROM `item_template` WHERE `id` BETWEEN 2032 AND 2074;
DELETE FROM `part`          WHERE `id` BETWEEN 2099 AND 2212;



SELECT COUNT(*) AS `item_moi` FROM `item_template` WHERE `id` BETWEEN 2032 AND 2041;
SELECT COUNT(*) AS `part_moi` FROM `part` WHERE `id` BETWEEN 2099 AND 2128;
